import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"تخمینی تکرار نظام کی تفصیلی وضاحت","description":"","frontmatter":{},"headers":[],"relativePath":"ur/0011-推演迭代体系详解.md","filePath":"ur/0011-推演迭代体系详解.md"}'),d={name:"ur/0011-推演迭代体系详解.md"};function o(i,t,h,n,u,s){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="تخمینی-تکرار-نظام-کی-تفصیلی-وضاحت" tabindex="-1">تخمینی تکرار نظام کی تفصیلی وضاحت <a class="header-anchor" href="#تخمینی-تکرار-نظام-کی-تفصیلی-وضاحت" aria-label="Permalink to &quot;تخمینی تکرار نظام کی تفصیلی وضاحت&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>11</td></tr><tr><td>ماڈیول</td><td>کائنات کے قوانین اور سادھائی کے نظام</td></tr><tr><td>کلیدی الفاظ</td><td>تخمینی تکرار، سو گنا اضافہ، تخمینی صلاحیت، بنیادی تین بنیادیں، دانشورانہ ارتقاء</td></tr></tbody></table><h2 id="اولًا-نظام-کا-عمومی-جائزہ" tabindex="-1">اولًا. نظام کا عمومی جائزہ <a class="header-anchor" href="#اولًا-نظام-کا-عمومی-جائزہ" aria-label="Permalink to &quot;اولًا. نظام کا عمومی جائزہ&quot;">​</a></h2><p>تخمینی تکرار نظام تین سو بنیادی سادھائی کے نظاموں میں پہلا نظام ہے، &quot;بنیادی تین بنیادیوں&quot; میں پہلے نمبر پر ہے، اور یہ تمام سادھائی کے نظاموں کی بنیاد اور پیش خیمہ ہے۔ یہ نظام &quot;تخمین&quot; کو بنیادی طریقہ کے طور پر، &quot;تکرار&quot; کو بنیادی عمل کے طور پر لیتا ہے، اور مسلسل تخمین، تصدیق، ترمیم، بہتری کے ذریعے سادھک کی اپنی صلاحیت اور سادھائی کے راستے کی دوہری ارتقاء حاصل کرتا ہے۔ تخمینی تکرار نظام کی سب سے بڑی خصوصیت یہ ہے کہ وہ دوگنا پھلوں کی تکنیکی اطلاق کے ذریعے فراہم کردہ &quot;سو گنا سادھائی تخمینی اضافہ&quot; کا استعمال کرتے ہوئے سادھک کی تخمینی صلاحیت کو عام سطح کے سو گنا تک بڑھاتی ہے، اور اس طرح سادھائی کے عمل اور نظریاتی جدت کو بہت زیادہ تیز کرتی ہے۔</p><p>تخمینی تکرار نظام دانشورانہ، تحقیقی، تخلیقی نوعیت کی زندگیوں کے لیے موزوں ہے۔ جو لوگ منطقی سوچ، نظریاتی تجزیہ، اختراعی دریافت میں مہارت رکھتے ہیں، ان کے لیے یہ نظام ان کی فطری صلاحیت کے فوائد کو زیادہ سے زیادہ ظاہر کر سکتا ہے۔ اس کے ساتھ ساتھ، تخمینی تکرار نظام دوسرے تمام نظاموں کا &quot;بنیادی نظام&quot; بھی ہے — کسی بھی نظام کے سادھک تخمینی تکرار نظام کو سیکھ کر اپنے سادھائی کے طریقے کو بہتر بنا سکتے ہیں، اور رکاوٹوں کو عبور کرنے کو تیز کر سکتے ہیں۔</p><h2 id="ثانیًا-نظام-کا-بنیادی-اصول" tabindex="-1">ثانیًا. نظام کا بنیادی اصول <a class="header-anchor" href="#ثانیًا-نظام-کا-بنیادی-اصول" aria-label="Permalink to &quot;ثانیًا. نظام کا بنیادی اصول&quot;">​</a></h2><p>تخمینی تکرار نظام کے بنیادی اصول کو &quot;تخمین—تصدیق—تکرار&quot; تین چکروں کے چکر کے طور پر خلاصہ کیا جا سکتا ہے:</p><h3 id="_2-1-تخمینی-چکر" tabindex="-1">2.1 تخمینی چکر <a class="header-anchor" href="#_2-1-تخمینی-چکر" aria-label="Permalink to &quot;2.1 تخمینی چکر&quot;">​</a></h3><p>تخمین سے مراد سادھک کی طرف سے شعور کے ڈومین میں سادھائی کے راستے، توانائی کے چلانے، قوانین کی تبدیلی کے بارے میں پہلے سے نقل و حساب کرنا ہے۔ تخمین کی اصلیت یہ ہے کہ حقیقی توانائی اور وسائل خرچ کیے بغیر، شعور کی گنتی کے ذریعے سادھائی کی مختلف امکانات کو پہلے سے آزمایا جائے۔ تخمین کا معیار سادھک کی تخمینی صلاحیت، علم کا ذخیرہ، قوانین کی گہری سمجھ — ان تین عوامل پر منحصر ہے۔</p><p>دوگنا پھلوں کی ٹیکنالوجی کی مدد سے، سادھک کی تخمین کی رفتار اور درستگی میں سو گنا اضافہ ہوتا ہے۔ اس کا مطلب یہ ہے کہ جو تخمینی حساب مکمل کرنے میں اصل میں سو سال لگتے تھے، سو گنا اضافے کے تحت صرف ایک سال لگتے ہیں؛ جو توانائی کے چلانے کو اصل میں صرف موٹے طور پر نقل کیا جا سکتا تھا، اب ہر توانائی کے ذرے کی رفتار تک درست کیا جا سکتا ہے۔</p><h3 id="_2-2-تصدیقی-چکر" tabindex="-1">2.2 تصدیقی چکر <a class="header-anchor" href="#_2-2-تصدیقی-چکر" aria-label="Permalink to &quot;2.2 تصدیقی چکر&quot;">​</a></h3><p>تصدیق سے مراد تخمین کے نتائج کو حقیقت میں چھوٹے پیمانے پر تجربہ اور جانچ کرنا ہے۔ آخر کار، تخمین شعور میں نقل ہے، اور حقیقت کے ساتھ اس میں فرق ہو سکتا ہے۔ تصدیقی چکر کا کام یہ ہے کہ کنٹرول شدہ تجربات کے ذریعے تخمین کے نتائج کی درستگی اور عملداری کی جانچ کی جائے، اور تخمین میں غیر متوقع مسائل کو دریافت کیا جائے۔</p><p>تصدیقی چکر &quot;کم از کم خطرے کے اصول&quot; پر عمل کرتا ہے: تمام تصدیقی تجربات کو الگ تھلگ جگہ میں کرنا ضروری ہے، کم از کم توانائی کا استعمال کرنا ضروری ہے، اور اس بات کو یقینی بنانا ضروری ہے کہ اگر تجربہ ناکام بھی ہو جائے تو سادھک کے خود یا آس پاس کے ماحول کو کوئی نقصان نہ پہنچے۔ تصدیق کے نتائج کو ڈیٹا کی صورت میں ریکارڈ کیا جاتا ہے، اور ترمیم کے لیے تخمینی چکر میں واپس بھیجا جاتا ہے۔</p><h3 id="_2-3-تکراری-چکر" tabindex="-1">2.3 تکراری چکر <a class="header-anchor" href="#_2-3-تکراری-چکر" aria-label="Permalink to &quot;2.3 تکراری چکر&quot;">​</a></h3><p>تکرار سے مراد تصدیق کے نتائج کی بنیاد پر تخمینی ماڈل میں ترمیم اور بہتری کرنا، اور پھر اگلی دور کی تخمین میں داخل ہونا ہے۔ ہر بار تکرار سے سادھک کی قوانین کی سمجھ مزید گہری ہوتی ہے، توانائی کے کنٹرول میں مزید درستگی آتی ہے، اور سادھائی کے راستے کا انتخاب مزید بہتر ہوتا ہے۔ تکرار سادہ تکرار نہیں ہے، بلکہ سرپل طور پر اوپر کی طرف بڑھنے والا ارتقاء کا عمل ہے۔</p><p>تین چکروں کے چلانے کی فریکوئنسی سادھک کی سطح اور دوگنا پھلوں کے اضافے کی شدت پر منحصر ہے۔ ابتدائی مرحلے میں، ایک مکمل چکر مکمل کرنے میں کئی دن لگ سکتے ہیں؛ اعلیٰ مرحلے میں، سادھک ایک لمحے میں ہزاروں بار تکرار مکمل کر سکتا ہے، اور &quot;اچانک سمجھ&quot; قسم کی کامیابی حاصل کر سکتا ہے۔</p><h2 id="ثالثًا-سطح-کی-تقسیم-اور-ہر-مرحلے-کی-خصوصیات" tabindex="-1">ثالثًا. سطح کی تقسیم اور ہر مرحلے کی خصوصیات <a class="header-anchor" href="#ثالثًا-سطح-کی-تقسیم-اور-ہر-مرحلے-کی-خصوصیات" aria-label="Permalink to &quot;ثالثًا. سطح کی تقسیم اور ہر مرحلے کی خصوصیات&quot;">​</a></h2><p>تخمینی تکرار نظام پانچ بنیادی سطحوں میں تقسیم ہے، ہر سطح کی واضح خصوصیات اور معائنہ کے معیار ہیں:</p><table tabindex="0"><thead><tr><th>سطح</th><th>نام</th><th>بنیادی خصوصیت</th><th>تخمینی صلاحیت</th><th>نمایاں صلاحیت</th></tr></thead><tbody><tr><td>پہلی سطح</td><td>ابتدائی بصیرت</td><td>ابتدائی طور پر تخمینی شعور قائم، سادہ سادھائی کے راستے کی تخمین کرنے کے قابل</td><td>عام تخمین رفتار کا 1-10 گنا</td><td>بنیادی تخمینی فن: شعور میں ایک قدم کی سادھائی کو پہلے سے آزمانے کے قابل</td></tr><tr><td>دوسری سطح</td><td>تخمین</td><td>تخمینی صلاحیت میں بہت زیادہ اضافہ، پیچیدہ کثیر متغیر تخمین کرنے کے قابل</td><td>عام تخمین رفتار کا 10-50 گنا</td><td>کثیر جہتی تخمین: ایک ساتھ متعدد سادھائی کے راستوں کی تخمین اور موازنہ کرنے کے قابل</td></tr><tr><td>تیسری سطح</td><td>تکرار</td><td>مکمل تخمین—تصدیق—تکرار چکر پر عبور، خود بخود سادھائی کے راستے کو بہتر بنانے کے قابل</td><td>عام تخمین رفتار کا 50-100 گنا</td><td>خود بہتر تکرار: سادھائی کا راستہ خود بخود بہتر ہوتا ہے، رکاوٹ عبور کی رفتار میں بہت زیادہ اضافہ</td></tr><tr><td>چوتھی سطح</td><td>انضمام</td><td>تخمینی صلاحیت سادھائی کے تمام پہلوؤں میں داخل ہو جاتی ہے، تخمین اور حقیقی جنگ کے بے ہنگام انضمام کو حاصل کرتی ہے</td><td>عام تخمین رفتار کا 100-500 گنا</td><td>حقیقی جنگ کی تخمین: جنگ کے دوران مخالف کی تمام ممکنہ کارروائیوں کی حقیقی وقت میں تخمین اور بہترین جواب تیار کرنے کے قابل</td></tr><tr><td>پانچویں سطح</td><td>بنیاد</td><td>تخمین کائنات کے بنیادی قوانین کو چھوتی ہے، قانون کے خود چلانے اور تبدیلی کی تخمین کرنے کے قابل</td><td>500 گنا سے زیادہ، لامحدود تخمین کے قریب</td><td>قانون کی تخمین: نئے قانون کے اطلاق کے طریقے کی تخمین کرنے کے قابل، یہاں تک کہ قانون کے باریک ایڈجسٹمنٹ اور بہتری میں حصہ لینے کے قابل</td></tr></tbody></table><p>ہر سطح کی کامیابی کے لیے &quot;تخمینی معائنہ&quot; پاس کرنا ضروری ہے: لنگر نیٹ ورک کی نگرانی میں، مقررہ مشکل کی تخمینی کام مکمل کرنا، اور معائنہ پاس کرنے کے بعد ہی سطح کی بلندی کی تصدیق کی جا سکتی ہے۔</p><h2 id="رابعًا-نظام-میں-دوگنا-پھلوں-کی-ٹیکنالوجی-کا-اطلاق" tabindex="-1">رابعًا. نظام میں دوگنا پھلوں کی ٹیکنالوجی کا اطلاق <a class="header-anchor" href="#رابعًا-نظام-میں-دوگنا-پھلوں-کی-ٹیکنالوجی-کا-اطلاق" aria-label="Permalink to &quot;رابعًا. نظام میں دوگنا پھلوں کی ٹیکنالوجی کا اطلاق&quot;">​</a></h2><p>دوگنا پھلوں کی تکنیکی اطلاق وہ بنیادی تکنیکی معاونت ہے جس کی وجہ سے تخمینی تکرار نظام سو گنا تخمینی اضافہ حاصل کر سکتا ہے۔ نظام میں اس کا اطلاق درج ذیل شامل ہے:</p><h3 id="_4-1-شعور-کی-تیز-رفتاری" tabindex="-1">4.1 شعور کی تیز رفتاری <a class="header-anchor" href="#_4-1-شعور-کی-تیز-رفتاری" aria-label="Permalink to &quot;4.1 شعور کی تیز رفتاری&quot;">​</a></h3><p>دوگنا پھلوں کی ٹیکنالوجی سادھک کے شعور کے ڈومین کی گنتی کی رفتار کو تیز کر سکتی ہے، اور شعور میں وقت کے بہاؤ کو حقیقی وقت سے مختلف بنا سکتی ہے۔ سو گنا اضافے کے تحت، جب سادھک شعور میں سو سیکنڈ کی تخمین چلاتا ہے، تو حقیقت میں صرف ایک سیکنڈ گزرتا ہے۔ یہ شعور کی تیز رفتاری اضافی زندگی کی توانائی خرچ نہیں کرتی، بلکہ قانون کی گونج کے ذریعے خالص شعور کی سطح کی تیز رفتاری ہے۔</p><h3 id="_4-2-متوازی-تخمین" tabindex="-1">4.2 متوازی تخمین <a class="header-anchor" href="#_4-2-متوازی-تخمین" aria-label="Permalink to &quot;4.2 متوازی تخمین&quot;">​</a></h3><p>دوگنا پھلوں کی ٹیکنالوجی سادھک کو ایک ساتھ متعدد آزاد تخمینی دھاگے چلانے میں مدد دیتی ہے۔ ابتدائی سادھک ایک ساتھ 3-5 راستوں کی تخمین کر سکتے ہیں، اعلیٰ درجے کے سادھک ایک ساتھ سینکڑوں راستوں کی تخمین کر سکتے ہیں، اور مختلف امکانات کا وسیع موازنہ اور انتخاب کر سکتے ہیں۔</p><h3 id="_4-3-تخمین-کی-درستگی-میں-اضافہ" tabindex="-1">4.3 تخمین کی درستگی میں اضافہ <a class="header-anchor" href="#_4-3-تخمین-کی-درستگی-میں-اضافہ" aria-label="Permalink to &quot;4.3 تخمین کی درستگی میں اضافہ&quot;">​</a></h3><p>دوگنا پھلوں کی ٹیکنالوجی نہ صرف تخمین کی رفتار بڑھاتی ہے، بلکہ تخمین کی درستگی بھی بڑھاتی ہے۔ سو گنا اضافے کے تحت، سادھک زیادہ باریک توانائی کی تبدیلیوں اور قانون کے اتار چڑھاو کو محسوس کر سکتا ہے، اور تخمین کے نتائج کو حقیقت کے زیادہ قریب لا سکتا ہے۔</p><h3 id="_4-4-تخمینی-یادداشت-کو-مستقل-کرنا" tabindex="-1">4.4 تخمینی یادداشت کو مستقل کرنا <a class="header-anchor" href="#_4-4-تخمینی-یادداشت-کو-مستقل-کرنا" aria-label="Permalink to &quot;4.4 تخمینی یادداشت کو مستقل کرنا&quot;">​</a></h3><p>دوگنا پھلوں کی ٹیکنالوجی تخمین کے عمل میں حاصل کردہ بصیرت اور سمجھ کو طویل المدت یادداشت کے طور پر مستقل کر سکتی ہے، اور تخمین کے نتائج کو بھول جانے سے روک سکتی ہے۔ سادھک کسی بھی وقت ماضی کی تخمینی ریکارڈ حاصل کر سکتا ہے، اور جائزہ اور دوبارہ تجزیہ کر سکتا ہے۔</p><h2 id="خامسًا-نظام-کے-سادھائی-کے-طریقے-اور-روزمرہ-کی-مشق" tabindex="-1">خامسًا. نظام کے سادھائی کے طریقے اور روزمرہ کی مشق <a class="header-anchor" href="#خامسًا-نظام-کے-سادھائی-کے-طریقے-اور-روزمرہ-کی-مشق" aria-label="Permalink to &quot;خامسًا. نظام کے سادھائی کے طریقے اور روزمرہ کی مشق&quot;">​</a></h2><p>تخمینی تکرار نظام کی سادھائی گھر میں بند ہو کر گاڑی بنانا نہیں ہے، بلکہ اسے عملی سے گہرا جوڑنے کی ضرورت ہے۔ روزمرہ کی سادھائی کے طریقے درج ذیل شامل ہیں:</p><ol><li><strong>روزانہ تخمینی تربیت</strong>: ہر روز مقررہ وقت پر تخمینی تربیت چلانا، سادہ توانائی کے چلانے کی تخمین سے بتدریج پیچیدہ قانون کی تبدیلی کی تخمین کی طرف منتقل ہونا</li><li><strong>تخمینی ڈائری ریکارڈنگ</strong>: ہر بار تخمین کے عمل، نتائج، تصدیق کی صورت حال کو ریکارڈ کرنا، ذاتی تخمینی ڈیٹا بیس بنانا</li><li><strong>بین النظام تخمینی اطلاق</strong>: تخمینی صلاحیت کو دوسرے سادھائی کے نظاموں کی سادھائی میں اطلاق کرنا، دوسرے نظاموں کے سادھائی کے راستے کو بہتر بنانا</li><li><strong>تخمینی تبادلہ اور بحث</strong>: دوسرے تخمینی تکرار نظام کے سادھکوں کے ساتھ تخمینی تجربات کا تبادلہ کرنا، باہمی طور پر تخمین کے نتائج کی تصدیق کرنا</li><li><strong>تخمینی مقابلے میں حصہ لینا</strong>: تہذیب کی طرف سے منعقد کردہ تخمینی مقابلے میں حصہ لینا، مقابلے کے ذریعے تخمینی صلاحیت بڑھانا</li></ol><h2 id="سادسًا-نظام-کے-فوائد-اور-حدود" tabindex="-1">سادسًا. نظام کے فوائد اور حدود <a class="header-anchor" href="#سادسًا-نظام-کے-فوائد-اور-حدود" aria-label="Permalink to &quot;سادسًا. نظام کے فوائد اور حدود&quot;">​</a></h2><h3 id="_6-1-فوائد" tabindex="-1">6.1 فوائد <a class="header-anchor" href="#_6-1-فوائد" aria-label="Permalink to &quot;6.1 فوائد&quot;">​</a></h3><ul><li>سادھائی کی کارکردگی انتہائی زیادہ: سو گنا تخمینی اضافہ سادھائی کی رفتار کو عام نظاموں سے کہیں زیادہ بڑھاتا ہے</li><li>رکاوٹ عبور کی صلاحیت مضبوط: تخمین کے ذریعے رکاوٹ عبور کا بہترین راستہ تلاش کیا جا سکتا ہے</li><li>آفاقیت مضبوط: تخمینی صلاحیت کسی بھی دوسرے نظام کی سادھائی میں اطلاق کی جا سکتی ہے</li><li>حفاظت زیادہ: زیادہ تر سادھائی شعور میں مکمل ہوتی ہے، ذہنی انحراف کے خطرے کو کم کرتی ہے</li><li>جدت کی صلاحیت مضبوط: تخمین نظریاتی جدت کا بنیادی طریقہ ہے، اس نظام کے سادھک اکثر نئے سادھائی کے طریقے اور نئی ٹیکنالوجی کے موجد ہوتے ہیں</li></ul><h3 id="_6-2-حدود" tabindex="-1">6.2 حدود <a class="header-anchor" href="#_6-2-حدود" aria-label="Permalink to &quot;6.2 حدود&quot;">​</a></h3><ul><li>عقل اور نفسیات پر زیادہ دباؤ: منطقی سوچ کی صلاحیت نہ رکھنے والے یا نفسیات بے چین سادھکوں کے لیے موزوں نہیں</li><li>ابتدائی مرحلے میں جنگی صلاحیت کمزور: ابتدائی مرحلے میں بنیادی طور پر شعور میں سادھائی ہوتی ہے، حقیقی جنگی صلاحیت میں اضافہ سست ہوتا ہے</li><li>تخمین پر زیادہ انحصار حقیقی جنگ کو نظر انداز کر سکتا ہے: کچھ سادھک تخمین میں مگن رہ کر حقیقی تصدیق کو نظر انداز کر سکتے ہیں</li><li>دوگنا پھلوں کی ٹیکنالوجی پر انحصار: سو گنا اضافے کے لیے دوگنا پھلوں کی ٹیکنالوجی کی مدد درکار ہے، ٹیکنالوجی کا احاطہ کم علاقوں میں اثر محدود ہے</li></ul><h2 id="ساتواں-دوسرے-نظاموں-کے-ساتھ-مطابقت" tabindex="-1">ساتواں. دوسرے نظاموں کے ساتھ مطابقت <a class="header-anchor" href="#ساتواں-دوسرے-نظاموں-کے-ساتھ-مطابقت" aria-label="Permalink to &quot;ساتواں. دوسرے نظاموں کے ساتھ مطابقت&quot;">​</a></h2><p>تخمینی تکرار نظام &quot;بنیادی تین بنیادیوں&quot; میں پہلے کے طور پر، دوسرے تمام سادھائی کے نظاموں کے ساتھ اچھی مطابقت رکھتا ہے۔ خاص طور پر:</p><ul><li>زندگی کے چکر کے نظام کے ساتھ مشترکہ سادھائی: زندگی کی توانائی کے چکر کا بہترین راستہ تخمین کر سکتا ہے، زندگی کے چکر کے نظام کی سادھائی کو تیز کر سکتا ہے</li><li>خلائی قانونی ترتیب کے نظام کے ساتھ مشترکہ سادھائی: خلائی قوانین کے مختلف اطلاق کے طریقے تخمین کر سکتا ہے، خلائی کنٹرول کی درستگی بڑھا سکتا ہے</li><li>شعور کی بلندی کے زمرے کے نظاموں کے ساتھ مشترکہ سادھائی: تخمین خود ہی شعور کی مشق ہے، شعور کی بلندی کو تیز کر سکتا ہے</li><li>اطلاقی انجینئرنگ کے زمرے کے نظاموں کے ساتھ مشترکہ سادھائی: تخمین قانون کی انجینئرنگ ڈیزائن کا بنیادی طریقہ ہے، انجینئرنگ ڈیزائن کی کارکردگی کو بہت زیادہ بڑھا سکتا ہے</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>تخمینی تکرار نظام لنگر سمبیوٹک تہذیب کے سادھائی کے نظام کی بنیاد اور پیش خیمہ ہے۔ یہ سو گنا تخمینی اضافے کو ہتھیار کے طور پر، تخمین—تصدیق—تکرار چکر کو طریقہ کے طور پر لیتا ہے، اور سادھکوں کے لیے ایک موثر، محفوظ، آفاقی ارتقاء کا راستہ فراہم کرتا ہے۔ تخمینی تکرار نظام کا حتمی مقصد یہ ہے کہ ہر سادھک کو اپنی ارتقاء کا &quot;سربراہ سائنسدان&quot; بنا دیا جائے، اور مسلسل تخمین اور تکرار کے ذریعے اپنے لیے سب سے موزوں ارتقاء کا راستہ تلاش کیا جائے، اور پوری تہذیب کے قانون کی جدت اور تکنیکی ترقی میں حصہ لیا جائے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (تین سو بنیادی سادھائی کے نظام کا عمومی جائزہ)</li><li>16-倍增果实技术化原理 (دوگنا پھلوں کی تکنیکی بنیاد)</li><li>14-修炼境界统一划分 (سادھائی کی سطح کی یکجا تقسیم)</li></ul>',45)])])}const p=a(d,[["render",o]]);export{c as __pageData,p as default};
